def human(n):
    rs = open(f"/tmp/dgc-{n}-stale.txt", encoding="utf-8").read()
    ra = open(f"/tmp/dgc-{n}-after.txt", encoding="utf-8").read()
    sj, aj = load(f"/tmp/dgc-{n}-stale.json"), load(f"/tmp/dgc-{n}-after.json")
