    drop = {r["module"]: len(ROW_DROP[n](r["module"])) for r in sj["results"]}
    V = [r["module"] for r in sj["results"] if vanishes(n, r)]
    assert all(i >= MAX_ROWS for i, r in enumerate(sj["results"]) if r["module"] in V) and (not V or len(sj["results"]) - len(V) > MAX_ROWS), (n, "an absent row is predicted only inside the rollup", V)
    if not NOTE[n] and not any(drop.values()):
        assert ra == rs, (n, "nothing is predicted to move: the human output is byte-identical, caveat text included")
        return rs.splitlines(), ra.splitlines()
    assert rs.endswith("\n") == ra.endswith("\n"), (n, "trailing newline")
    st, af = rs.splitlines(), ra.splitlines()
    assert UND not in rs and not any(l.startswith("declared set may be incomplete") for l in st), (n, "no marking on the v0.19.0 render")
    rows = [i for i, l in enumerate(af) if l.startswith("  used ")]
    if NOTE[n]:
        assert af.count(NOTE[n]) == 1 and rows and af.index(NOTE[n]) < rows[0], (n, "the marking line renders exactly once, above the module rows")
        af = [l for l in af if l != NOTE[n]]
    assert not any(l.startswith("declared set may be incomplete") for l in af), (n, "an unpredicted marking line")
    keep_caveat = any(r["declared_but_unobserved"] > 0 for r in aj["results"])
    exp, mod = [], None
    for l in st:
        if l.startswith(CAVEAT) and not keep_caveat:
            continue  # the one predicted disappearance: no row keeps a declared_but_unobserved count; otherwise the caveat is compared verbatim
        if l.startswith("  used "):
            k = drop[mod] if mod in drop else drop[""]
            l = re.sub(r"no static import found (\d+)", lambda m: f"no static import found {int(m.group(1)) - k}", l)
            if NOTE[n]:
