        elif l.startswith("(+") and " more module" in l:
            rolled = sum(drop[r["module"]] for r in sj["results"][MAX_ROWS:])
            l = re.sub(r"(\d+) declared deps?\b", lambda m: (lambda t: f"{t} declared dep{'' if t == 1 else 's'}")(int(m.group(1)) - rolled), l)
