    reg = json.load(open(f"/private/tmp/DEPS-GRADLE-CATALOG-1-{n}-before/registry.json", encoding="utf-8"))["repos"][0]
    con = sqlite3.connect("file:" + reg["db_path"] + "?immutable=1", uri=True)
